/** The bytes of one fixture font. */
export function fontBytes(name: string): Uint8Array {
  const font = FONT_FILES[name];
  if (!font) throw new Error('No fixture font named ' + name);
  return new Uint8Array(Buffer.from(font.base64, 'base64'));
}
